/** offline search — name/tag substring match, ranked: name prefix > name > tag */
export function searchIcons(query: string, limit = 120): IconDef[] {
  const q = query.trim().toLowerCase()
  if (!q) return ICONS.slice(0, limit)
  const scored: { icon: IconDef; score: number }[] = []
  for (const icon of ICONS) {
    const name = icon.name.toLowerCase()
    let score = -1
    if (name.startsWith(q)) score = 0
    else if (name.includes(q)) score = 1
    else if (icon.tags.some((t) => t.startsWith(q))) score = 2
    else if (icon.tags.some((t) => t.includes(q))) score = 3
    if (score >= 0) scored.push({ icon, score })
  }
  return scored.sort((a, b) => a.score - b.score || a.icon.name.localeCompare(b.icon.name)).slice(0, limit).map((s) => s.icon)
}
